# libc.map — libc.so 导出符号版本脚本
#
# 规则：头文件即契约 + 跨 .so 引用。
#   - global: user/include/** 下声明且 libc.so 实际定义的符号，全部导出
#   - 必要的 __ 事实 ABI 符号（crt0/assert/errno 跨 .so 调用）显式列入
#   - local: *; 兜底：所有未列入 global 的符号（内部实现、_Z mangled、
#     __libc_run_*、__pthread_key_*、kvfmt_*、atexit_* 等）一律 hidden
#
# 单版本节点 LIBC_1.0；将来 Proton 二进制兼容需要符号版本时加 GLIBC_2.x 节点。

LIBC_1.0 {
global:
    /* <stdio.h> — musl upstream src/stdio (musl_stdio_objs, stdio.md). FILE is
     * musl's struct _IO_FILE; the full narrow-char stdio family now ships:
     * printf/scanf engines + wrappers, byte getc/putc family + *_unlocked,
     * fopen/fclose/fread/fwrite/fseek/ftell + fseeko/ftello, getdelim/getline,
     * open_memstream/fmemopen/fopencookie, flockfile/..., asprintf/vasprintf.
     * stdin/stdout/stderr are OBJECT symbols (musl stdin.c/stdout.c/stderr.c).
     * Deliberately NOT exported (stay hidden under local: *;):
     *   rename        — in musl_unistd_objs (unistd block below), not re-listed here
     *   dprintf/vdprintf — musl native stdio impl (routes through vfprintf); not
     *                   public. The loader resolves to them but no app consumer
     *                   needs them exported.
     *   __isoc99_x / _IO_x / __getdelim / x_used — internal aliases (weak_alias), no
     *                   consumer references them (not declared in <stdio.h>)
     *   wide-char w* family (fwprintf/fgetwc/wscanf/...) — NOW exported under the
     *                   <wchar.h> block below (musl_stdio_objs compiles them; deps
     *                   satisfied by musl_wchar_objs + musl_time_objs). Only the
     *                   *_unlocked and __isoc99_* aliases stay hidden here. */
    asprintf; clearerr; clearerr_unlocked; ctermid; fclose; fdopen; feof;
    feof_unlocked; ferror; ferror_unlocked; fflush; fflush_unlocked; fgetc;
    fgetc_unlocked; fgetln; fgetpos; fgets; fgets_unlocked; fileno;
    fileno_unlocked; flockfile; fmemopen; fopen; fopencookie; fprintf; fputc;
    fputc_unlocked; fputs; fputs_unlocked; fread; fread_unlocked; freopen;
    fscanf; fseek; fseeko; fsetpos; ftell; ftello; ftrylockfile; funlockfile;
    fwrite; fwrite_unlocked; getc; getchar; getchar_unlocked; getc_unlocked;
    getdelim; getline; gets; getw; open_memstream; perror; printf; putc;
    putchar; putchar_unlocked; putc_unlocked; puts; putw; remove; rewind;
    scanf; setbuf; setbuffer; setlinebuf; setvbuf; snprintf; sprintf; sscanf;
    stdin; stdout; stderr; ungetc; vasprintf; vfprintf; vfscanf; vprintf;
    vscanf; vsnprintf; vsprintf; vsscanf;

    /* <stdlib.h> — pure compute + startup/env/exit chain from musl_stdlib_objs
     * (stdlib.md). abs/labs/llabs/imaxabs/imaxdiv/div/ldiv/lldiv, atoi/atol/
     * atoll, strtol/strtoul/strtoll/strtoull/strtoimax/strtoumax, strtod/strtof/
     * strtold/atof, qsort/bsearch, rand/srand/rand_r, getenv/setenv/putenv/
     * unsetenv/clearenv/environ, exit/atexit/abort/quick_exit/at_quick_exit/
     * _Exit, __libc_start_main all come from musl upstream now. */
    abs; atexit; atoi; atol; atoll; calloc; exit; free; labs; llabs;
    malloc; qsort; bsearch; rand; rand_r; realloc; srand; strtol; strtoul;
    strtoll; strtoull; strtod; strtof; strtold; atof; div; ldiv; lldiv;
    imaxabs; imaxdiv; strtoimax; strtoumax;
    getenv; setenv; putenv; unsetenv; clearenv; environ;
    _Exit; quick_exit; at_quick_exit; __cxa_atexit; __cxa_finalize;
    mkstemp; mktemp; realpath;

    /* <string.h> — musl upstream (src/string/* + x86_64 asm memcpy/memmove/memset
     * + src/misc basename). The extension symbols musl compiles but we do NOT
     * list here (stpcpy/stpncpy/memrchr/strsep/strlcpy/strlcat/memccpy/mempcpy/
     * strchrnul/strcasestr/strverscmp/ffsl/ffsll/swab) are intentionally
     * unexported — `local: *;` hides them from the dynsym. strcoll/strxfrm/
     * strcoll_l/strxfrm_l/strcasecmp_l/strncasecmp_l are declared by musl's
     * <string.h>/<strings.h> but have NO implementation yet (src/locale/, not
     * compiled); 0 callers — deferred to the locale tier. */
    bzero; bcmp; bcopy; index; rindex; memcmp; memcpy; memmove; memset;
    memchr; memmem; strcat; strchr; strcmp; strcpy; strcspn; strdup;
    strerror; strerror_r; strerror_l; strlen; strncat; strncmp; strncpy; strndup;
    strpbrk; strrchr; strspn; strstr; strtok; strtok_r;
    strverscmp;
    basename;
    dirname;

    /* <strings.h> */
    ffs; strcasecmp; strncasecmp;

    /* <unistd.h> */
    access; faccessat; close; dup; dup2; _exit; ftruncate; getcwd; getpid; gettid;
    ioperm; isatty; lseek; memfd_create; mkdir; open; pipe; pipe2; read;
    rmdir; sched_yield; sleep; ttyname; unlink; unlinkat; rename; renameat;
    usleep; write;
    utimensat;
    symlink; symlinkat; readlinkat;
    link; linkat;
    getuid; geteuid; getgid; getegid; getppid; getpgrp; umask;
    gethostname; sethostname; alarm; pause;
    setitimer;
    truncate; fsync; sync;
    getpagesize; sysconf;
    nice; getpriority; setpriority;
    chown; fchown; fchownat; readlink;
    /* M1.1 — set*id ladder + getgroups (unistd.md §2.A1/A2). */
    setresuid; setresgid; setreuid; setregid; seteuid; setegid; getgroups;

    /* <fcntl.h> */
    openat; fcntl; posix_fallocate;

    /* <sys/file.h> */
    flock;

    /* <sys/uio.h> — musl src/unistd/{readv,writev}.c, compiled but hidden by local:* */
    readv; writev;

    /* <sys/socket.h> */
    accept4;
    socket; socketpair; accept; connect; bind; listen; shutdown;
    getsockname; getpeername; getsockopt; setsockopt;
    send; recv; sendto; recvfrom; sendmsg; recvmsg;

    /* <ctype.h> */
    isalnum; isalpha; isascii; isblank; iscntrl; isdigit; isgraph;
    islower; isprint; ispunct; isspace; isupper; isxdigit; tolower;
    toupper;

    /* <math.h> + <fenv.h> — musl src/math + src/fenv merged into libc (musl single-libc philosophy; libm.so is an empty -lm stub). */
    fesetround; fegetexceptflag; fesetexceptflag; feholdexcept; feupdateenv;
    __flt_rounds;
    acos;
    acosf;
    acosh;
    acoshf;
    acoshl;
    acosl;
    asin;
    asinf;
    asinh;
    asinhf;
    asinhl;
    asinl;
    atan;
    atan2;
    atan2f;
    atan2l;
    atanf;
    atanh;
    atanhf;
    atanhl;
    atanl;
    cbrt;
    cbrtf;
    cbrtl;
    ceil;
    ceilf;
    ceill;
    copysign;
    copysignf;
    copysignl;
    cos;
    cosf;
    cosh;
    coshf;
    coshl;
    cosl;
    drem;
    dremf;
    erf;
    erfc;
    erfcf;
    erfcl;
    erff;
    erfl;
    exp;
    exp10;
    exp10f;
    exp10l;
    exp2;
    exp2f;
    exp2l;
    expf;
    expl;
    expm1;
    expm1f;
    expm1l;
    fabs;
    fabsf;
    fabsl;
    fdim;
    fdimf;
    fdiml;
    feclearexcept;
    fegetenv;
    fegetround;
    feraiseexcept;
    fesetenv;
    fetestexcept;
    finite;
    finitef;
    floor;
    floorf;
    floorl;
    fma;
    fmaf;
    fmal;
    fmax;
    fmaxf;
    fmaxl;
    fmin;
    fminf;
    fminl;
    fmod;
    fmodf;
    fmodl;
    frexp;
    frexpf;
    frexpl;
    hypot;
    hypotf;
    hypotl;
    ilogb;
    ilogbf;
    ilogbl;
    j0;
    j0f;
    j1;
    j1f;
    jn;
    jnf;
    ldexp;
    ldexpf;
    ldexpl;
    lgamma;
    lgammaf;
    lgammaf_r;
    lgammal;
    lgammal_r;
    lgamma_r;
    llrint;
    llrintf;
    llrintl;
    llround;
    llroundf;
    llroundl;
    log;
    log10;
    log10f;
    log10l;
    log1p;
    log1pf;
    log1pl;
    log2;
    log2f;
    log2l;
    logb;
    logbf;
    logbl;
    logf;
    logl;
    lrint;
    lrintf;
    lrintl;
    lround;
    lroundf;
    lroundl;
    modf;
    modff;
    modfl;
    nan;
    nanf;
    nanl;
    nearbyint;
    nearbyintf;
    nearbyintl;
    nextafter;
    nextafterf;
    nextafterl;
    nexttoward;
    nexttowardf;
    nexttowardl;
    pow;
    pow10;
    pow10f;
    pow10l;
    powf;
    powl;
    remainder;
    remainderf;
    remainderl;
    remquo;
    remquof;
    remquol;
    rint;
    rintf;
    rintl;
    round;
    roundf;
    roundl;
    scalb;
    scalbf;
    scalbln;
    scalblnf;
    scalblnl;
    scalbn;
    scalbnf;
    scalbnl;
    signgam;
    significand;
    significandf;
    sin;
    sincos;
    sincosf;
    sincosl;
    sinf;
    sinh;
    sinhf;
    sinhl;
    sinl;
    sqrt;
    sqrtf;
    sqrtl;
    tan;
    tanf;
    tanh;
    tanhf;
    tanhl;
    tanl;
    tgamma;
    tgammaf;
    tgammal;
    trunc;
    truncf;
    truncl;
    y0;
    y0f;
    y1;
    y1f;
    yn;
    ynf;


    /* <time.h> — musl upstream (src/time/* + src/locale/langinfo.c via
     * musl_time_objs, time.md). clock_getres, clock_getcpuclockid, times
     * have no kernel syscall impl and return -ENOSYS (0 callers). The timer
     * family is NOT built (deferred, see todo.md). wcsftime IS built (in
     * musl_wchar_objs — see the <wchar.h> block below; its time deps resolve
     * via the merged libc).
     * timespec_to_tm (repo non-std) is deleted. */
    clock; clock_gettime; clock_settime; clock_getres; clock_getcpuclockid;
    ctime; ctime_r; asctime; asctime_r;
    difftime; clock_nanosleep; gettimeofday; gmtime; gmtime_r; localtime;
    localtime_r; mktime; timegm; nanosleep; strftime; strptime;
    time; timespec_get; times; utime; ftime; getdate; getdate_err;
    timezone; daylight; tzname; tzset;

    /* <langinfo.h> — C-locale provider compiled into musl_time_objs
     * (src/locale/langinfo.c) for __asctime/strftime/strptime. */
    nl_langinfo; nl_langinfo_l;

    /* <signal.h> */
    kill; raise; sigaction; signal; sigreturn; sigprocmask; sigpending; abort;
    sigaltstack;
    /* sigset_t helpers from musl src/signal/*.c (128-byte sigset_t) */
    sigemptyset; sigfillset; sigaddset; sigdelset; sigismember;
    /* SIGRTMIN/SIGRTMAX macros expand to these (musl private, exported for dyn ELF) */
    __libc_current_sigrtmin; __libc_current_sigrtmax;

    /* <termios.h> */
    tcgetattr; tcsetattr;

    /* <dirent.h> */
    closedir; opendir; readdir; scandir;
    telldir; seekdir; rewinddir; dirfd; readdir_r;
    fdopendir; versionsort;

    /* <errno.h> */
    __errno_location;

    /* <assert.h> */
    __assert_fail;

    /* <setjmp.h> */
    setjmp; longjmp; _setjmp; _longjmp;

    /* <sched.h> */
    sched_yield;

    /* <pthread.h> */
    pthread_attr_destroy; pthread_attr_getdetachstate;
    pthread_attr_getguardsize; pthread_attr_getstack;
    pthread_attr_getstacksize; pthread_attr_init;
    pthread_attr_setdetachstate; pthread_attr_setguardsize;
    pthread_attr_setstack; pthread_attr_setstacksize;
    pthread_barrier_destroy; pthread_barrier_init; pthread_barrier_wait;
    pthread_cancel;
    /* pthread_cleanup_push/pop are macros in musl <pthread.h>, not symbols */
    pthread_cond_broadcast; pthread_cond_destroy; pthread_cond_init;
    pthread_cond_signal; pthread_cond_wait; pthread_create; pthread_detach;
    pthread_equal; pthread_exit; pthread_getspecific; pthread_join;
    pthread_key_create; pthread_kill;
    pthread_mutexattr_destroy; pthread_mutexattr_gettype;
    pthread_mutexattr_init; pthread_mutexattr_settype;
    pthread_mutex_destroy; pthread_mutex_init; pthread_mutex_lock;
    pthread_mutex_timedlock; pthread_mutex_trylock; pthread_mutex_unlock;
    pthread_once; pthread_rwlock_destroy; pthread_rwlock_init;
    pthread_rwlock_rdlock; pthread_rwlock_unlock; pthread_rwlock_wrlock;
    pthread_self; pthread_setcancelstate; pthread_setcanceltype;
    pthread_setname_np; pthread_setspecific; pthread_sigmask;
    pthread_testcancel;

    /* <sys/stat.h> */
    fstat; fstatat; lstat; mkdir; mkdirat; mknod; stat; statx;
    chmod; fchmod; fchmodat;

    /* <sys/wait.h> */
    waitpid;

    /* <sys/mman.h> — musl upstream (src/mman/*.c via musl_mman_objs) + the
     * retained hand-written memfd_create (musl src/mman has none). mmap64 is
     * musl's LFS64(mmap) weak_alias of __mmap. msync/madvise/mlock/mlockall/
     * munlock/munlockall/mincore have no kernel handler (the syscall dispatch
     * returns -ENOSYS) but the symbols are exported so callers link; they
     * return -1/ENOSYS at runtime (POSIX-symbol-present / kernel-feature-absent
     * middle state, doc/design/todo.md). remap_file_pages is NOT built (musl
     * mremap.c does not define it). */
    memfd_create; mmap; mmap64; munmap; mprotect; mremap; msync;
    madvise; posix_madvise; mincore;
    mlock; munlock; mlockall; munlockall;
    shm_open; shm_unlink;

    /* <uchar.h> — musl src/multibyte/{c16,c32}{rtomb,rtoc16,rtoc32}.c (thin
     * wrappers over wcrtomb/mbrtowc in musl_multibyte_objs). C11 char16_t/
     * char32_t conversion. */
    c16rtomb; mbrtoc16; c32rtomb; mbrtoc32;

    /* <wctype.h> — musl src/ctype/{isw*,iswctype,wctrans,towctrans,wcwidth,
     * wcswidth}.c. Pure compute; locale_t pass-through (the _l variants forward
     * to the non-_l). Narrow ctype (isalnum/tolower/...) stays in user/lib/
     * ctype.c — NOT compiled here. iswdigit is both a real function
     * (iswdigit.c) and a macro in <wchar.h>/<wctype.h>; the symbol is exported
     * (the macro shadows it for C callers). */
    iswalnum; iswalpha; iswblank; iswcntrl; iswdigit; iswgraph; iswlower;
    iswprint; iswpunct; iswspace; iswupper; iswxdigit;
    iswctype; wctype; wctrans; towctrans; towlower; towupper;
    wcwidth; wcswidth;
    iswalnum_l; iswalpha_l; iswblank_l; iswcntrl_l; iswdigit_l; iswgraph_l;
    iswlower_l; iswprint_l; iswpunct_l; iswspace_l; iswupper_l; iswxdigit_l;
    iswctype_l; wctype_l; wctrans_l; towctrans_l; towlower_l; towupper_l;

    /* <wchar.h> — musl src/string wcs and wmem families + src/multibyte (btowc/wctob/
     * mbsrtowcs/...) + src/stdlib/{wcstol,wcstod}.c + src/time/wcsftime.c,
     * all compiled in musl_wchar_objs (mbsinit/mbrtowc/wcrtomb/wctomb come from
     * musl_multibyte_objs but <wchar.h> now declares them as public API, so
     * they are listed here to become GLOBAL — libc.map's local: otherwise
     * hides them). wcstoimax/wcstoumax are also declared in <inttypes.h>.
     * The wide-char stdio family below (wprintf/fwprintf/swprintf/wscanf/.../
     * fgetwc/fputwc/fgetws/fputws/ungetwc/fwide/getwc/getwchar/putwc/putwchar/
     * open_wmemstream) is compiled in musl_stdio_objs — its deps (isw families,
     * wcsnlen, btowc/wctob + __c_locale) are now satisfied by musl_wchar_objs +
     * musl_time_objs. Only the *_unlocked and __isoc99_* internal aliases stay
     * hidden (not declared in <wchar.h>, no consumer — same rule as narrow stdio).
     * DEFERRED (declared by <wchar.h>, NOT compiled, 0 callers, NOT listed):
     *   wcscoll/wcsxfrm/wcscoll_l/wcsxfrm_l — need src/locale (not built), same
     *     declare-only treatment as strcoll/strxfrm;
     *   wcsftime_l — weak_alias in wcsftime.c, no header decl consumer (hidden). */
    wcscpy; wcsncpy; wcscat; wcsncat; wcscmp; wcsncmp; wcschr; wcsrchr;
    wcscspn; wcsspn; wcspbrk; wcstok; wcslen; wcsnlen; wcsstr; wcswcs;
    wcscasecmp; wcsncasecmp; wcscasecmp_l; wcsncasecmp_l;
    wcsdup; wcpcpy; wcpncpy;
    wmemchr; wmemcmp; wmemcpy; wmemmove; wmemset;
    btowc; wctob; mblen; mbrlen; mbstowcs; wcstombs; mbsrtowcs; wcsrtombs;
    mbsnrtowcs; wcsnrtombs; mbtowc; wctomb;
    mbsinit; mbrtowc; wcrtomb;
    wcstof; wcstod; wcstold; wcstol; wcstoul; wcstoll; wcstoull;
    wcstoimax; wcstoumax;
    wcsftime;
    /* wide-char stdio (musl_stdio_objs, declared in <wchar.h>) */
    fwide; wprintf; fwprintf; swprintf; vwprintf; vfwprintf; vswprintf;
    wscanf; fwscanf; swscanf; vwscanf; vfwscanf; vswscanf;
    fgetwc; getwc; getwchar; fputwc; putwc; putwchar;
    fgetws; fputws; ungetwc; open_wmemstream;

    /* <sys/ioctl.h> */
    ioctl;

    /* <sys/poll.h> */
    poll;
    ppoll;

    /* <sys/epoll.h> */
    epoll_create; epoll_create1; epoll_ctl; epoll_wait; epoll_pwait;

    /* <sys/eventfd.h> */
    eventfd;

    /* <sys/timerfd.h> */
    timerfd_create; timerfd_settime;

    /* <sys/signalfd.h> */
    signalfd;

    /* <sys/mount.h> */
    mount;

    /* <sys/utsname.h> */
    uname;

    /* <sys/random.h> */
    getrandom; getentropy;
    arc4random_buf; arc4random_uniform;

    /* <sys/process.h> */
    execve; fork; getpgid; getsid; setpgid; setsid; spawn; setuid; setgid;

    /* <sys/ipc.h> — 微内核 IPC 用户态入口 */
    ipc_msg; ipc_msg_fd; ipc_msg_resp; ipc_notify; ipc_notify_fd;
    ipc_recv; ipc_req; ipc_resp;

    /* <sys/irq.h> */
    irq_bind;

    /* <sys/pci.h> */
    pci_dev_info_get;

    /* <sys/device.h> */
    device_register; device_register_shm; device_set_meta;

    /* <unistd.h> */
    wait_dev_ready;

    /* 事实 ABI：musl crt1/Scrt1 跨 .so 调用 */
    __libc_start_main;

    /* musl-compatible public ABI used by fused libc internals */
    prctl; strnlen;

    /* __dls2 在 ldso 自身 dynsym 里 find_sym("__dls3") 调用 stage-3 (dynlink.c:1439)；musl 自身 libc.so 本就导出 __dls3，被 local:* 误伤需显式导出 */
    __dls3;

    /* <dlfcn.h> — dlopen/dladdr/dl_iterate_phdr from fused dynlink.c; dlsym/dlclose/dlinfo/dlerror from musl_dl_objs (dlerror.c reads musl struct pthread's dlerror_buf/flag at %fs:0, now that musl_pthread provides the full layout). */
    dlopen; dlsym; dlclose; dlerror; dladdr; dlinfo; dl_iterate_phdr;

local:
    *;
};
